<script>
'use strict';
const csrf=<?=json_encode($csrf)?>,signedIn=<?=!empty($_SESSION['user_id'])?'true':'false'?>,form=document.getElementById('ideaForm'),button=document.getElementById('generate'),results=document.getElementById('results'),errorEl=document.getElementById('error');
async function digest(value){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}
async function challenge(){const res=await fetch('api/needle-bot-challenge.php',{cache:'no-store',credentials:'same-origin'}),data=await res.json();if(!res.ok||!data.challenge)throw Error(data.error||'Security check unavailable.');for(let i=0;i<3000000;i++){if(String(i).length>12)break;if(new RegExp('^0{'+Math.ceil(data.difficulty/4)+'}').test(await digest(data.challenge+':'+i)))return{challenge:data.challenge,counter:String(i)};if(i%400===0)await new Promise(resolve=>setTimeout(resolve,0))}throw Error('Security check could not finish. Try again.')}
function renderIdeas(text){const names=['STENCIL','LORE CARD','STYLE CARD','REFERENCE ARTWORK','PLACEMENT MOCKUP','PRINTER-READY ASSET'];const lines=String(text||'').trim().split(/\r?\n/),blocks=[];let current=null;for(const line of lines){if(/^\s*(?:\d+[.)]|(?:idea|concept)\s*\d+)/i.test(line)){if(current)blocks.push(current);current=line.replace(/^\s*(?:\d+[.)]|(?:idea|concept)\s*\d+)[\s:.)-]*/i,'').trim()}else if(current!==null&&line.trim()!==''){current+='\n'+line.trim()}}if(current)blocks.push(current);if(blocks.length<2){const paragraphs=String(text||'').split(/\n\s*\n/).map(value=>value.trim()).filter(Boolean);if(paragraphs.length>blocks.length)blocks.splice(0,blocks.length,...paragraphs)}const ideas=blocks.slice(0,6);if(!ideas.length)ideas.push(String(text||'No kit was returned.'));results.replaceChildren(...ideas.map((idea,index)=>{const card=document.createElement('article');card.className='bt-idea-card';const label=document.createElement('span');label.textContent=names[index]||'KIT PIECE '+String(index+1).padStart(2,'0');const title=document.createElement('h3');const parts=idea.split(/\n/,2);title.textContent=parts[0].slice(0,120);const body=document.createElement('p');body.textContent=parts.slice(1).join('\n')||'Needle Bot returned this piece as a compact production brief.';card.append(label,title,body);return card}))}
form.addEventListener('submit',async event=>{event.preventDefault();if(button.disabled)return;const concept=document.getElementById('concept').value.trim();if(!concept)return;const style=document.getElementById('style').value,placement=document.getElementById('placement').value,direction=document.getElementById('direction').value;const prompt='Act as Needle Bot, the Beyond Tattoo companion powered by Llama Jaguar. Create one cohesive six-piece tattoo kit from this brief. Return exactly six numbered blocks, in this exact order and with these exact headings: STENCIL, LORE CARD, STYLE CARD, REFERENCE ARTWORK, PLACEMENT MOCKUP, PRINTER-READY ASSET. For each block, provide a short title followed by concise, practical lines. The stencil block must describe clean line hierarchy and transfer priorities. The lore card must provide the story and symbolism. The style card must define palette, contrast, texture, and technique. The reference artwork block must be a detailed image brief for Jaguar Draw. The placement mockup block must describe body placement, scale, flow, and how the design wraps. The printer-ready asset block must specify a final black-line production asset with transparent background, 300 DPI, clean edges, suggested canvas ratio, and export checks; do not claim that a file was actually rendered. Keep the kit tattoo-safe, original in direction, and practical for a professional artist to refine. Do not add an introduction or conclusion.\n\nCore idea: '+concept+'\nStyle: '+style+'\nPlacement: '+placement+'\nDirection: '+direction;button.disabled=true;button.innerHTML='<span>✦</span> Needle Bot is building your kit…';errorEl.textContent='';results.innerHTML='<div class="bt-generator-loading">Needle Bot is building six production pieces…</div>';try{const proof=signedIn?null:await challenge();const response=await fetch('api/needle-bot-chat.php',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({language:'en',messages:[{role:'user',content:prompt}],proof})});const data=await response.json();if(!response.ok)throw Error(data.error||'Needle Bot is unavailable.');renderIdeas(data.message)}catch(error){results.innerHTML='<div class="bt-generator-empty"><h3>Needle Bot could not finish that kit</h3><p>Try again with a shorter brief.</p></div>';errorEl.textContent=error instanceof Error?error.message:'Needle Bot could not reply.'}finally{button.disabled=false;button.innerHTML='<span>✦</span> Generate six-piece tattoo kit'}});
</script>
